x = {-2: 1, -1: 2, 0: 3, 1: 4, 2: 5}


def g(k):
    return x.get(k, 0)


xe = {k: (g(k) + g(-k)) / 2 for k in x}
xo = {k: (g(k) - g(-k)) / 2 for k in x}

E = sum(v * v for v in x.values())
Ee = sum(v * v for v in xe.values())
Eo = sum(v * v for v in xo.values())

print("xe:", [xe[k] for k in sorted(xe)])
print("xo:", [xo[k] for k in sorted(xo)])
print("E =", E, "Ee+Eo =", Ee + Eo)
